// @ts-nocheck -- route types are generated by the embedded app.
// The group workspace: Plan canvas (months -> week bands -> activities with
// pickers), the per-month progress Matrix, and Members management. Everything
// authored here is projected into the Learner Journal / Activity Log through
// the ledger feed — this page is the ONLY place structural plan edits happen.
import { useMemo, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { createFileRoute, Link } from "@tanstack/react-router";
import {
  ArrowLeft, BookOpenText, CalendarDays, Check, ClipboardList, FileText,
  Headphones, ListChecks, Pencil, Plus, Tags, Trash2, UsersRound, Video, X,
} from "lucide-react";
import Swal from "sweetalert2";
import { Button } from "@/features/audit/learner-log-pro-manual/components/ui/button";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/features/audit/learner-log-pro-manual/components/ui/table";
import {
  addPlanActivities, archivePlanGroup, excludePlanActivity, getPlanGroup,
  getPlanMatrix, patchPlanActivity, pickAssignmentEvidence, pickAssignments,
  pickAttendanceGrid, pickKsbs, pickLmsGroupMembers, pickLmsGroups,
  pickMaterials, savePlanProgress, savePlanProgressBulk, suggestPlanMembers,
  updatePlanGroup, updatePlanMembers, updatePlanMonths,
  type AssignmentOption, type MaterialOption,
  type PlanActivity, type PlanGroupDetail, type PlanKsbs,
} from "@/features/audit/learner-log-pro-manual/lib/plan-api";

export const Route = createFileRoute("/groups/$groupId")({
  component: GroupWorkspacePage,
});

const field =
  "h-9 w-full rounded-md border border-border bg-card px-2.5 text-sm text-foreground outline-none focus:border-primary";

// Ayman's fixed week order lives in the add menu + default sort — never gates.
const ADD_MENU: Array<{ category: PlanActivity["category"] | "manual"; label: string; icon: typeof Video }> = [
  { category: "attendance", label: "Attendance day", icon: CalendarDays },
  { category: "video", label: "Videos / recordings", icon: Video },
  { category: "reading+quiz", label: "Reading + Quiz", icon: BookOpenText },
  { category: "audio", label: "Audio", icon: Headphones },
  { category: "assignment", label: "Assignment", icon: ClipboardList },
  { category: "manual", label: "Manual activity", icon: Plus },
];

const CATEGORY_ORDER = { attendance: 0, video: 1, "reading+quiz": 2, audio: 3, assignment: 5 };

function categoryChip(category: string) {
  const map: Record<string, string> = {
    attendance: "bg-[#e8eef0] text-[#31505d]",
    video: "bg-[#e5f3ef] text-[#16856b]",
    "reading+quiz": "bg-[#fbf0df] text-[#8a5a10]",
    audio: "bg-secondary text-muted-foreground",
    assignment: "bg-destructive/10 text-destructive",
  };
  return map[category] ?? "bg-muted text-muted-foreground";
}

function toast(title: string) {
  void Swal.fire({ toast: true, position: "top-end", icon: "success", title, showConfirmButton: false, timer: 1600 });
}

// Data-derived strings (activity titles, learner names, suggestion text) are
// interpolated into SweetAlert2 html — always escape them first.
function esc(value: unknown) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function fail(title: string, cause: unknown) {
  void Swal.fire({ icon: "error", title, text: cause instanceof Error ? cause.message : "Unexpected error." });
}

function warnSigned(warnings: Array<{ aptem_id: string; month: string }> | undefined) {
  if (warnings?.length) {
    void Swal.fire({
      icon: "warning",
      title: "Signed month affected",
      text: `${warnings.length} signed learner-month(s) are touched by this change — review their sign-off.`,
    });
  }
}

function GroupWorkspacePage() {
  const { groupId } = Route.useParams();
  const id = Number(groupId);
  const queryClient = useQueryClient();
  const group = useQuery({ queryKey: ["plan-group", id], queryFn: () => getPlanGroup(id) });
  const [tab, setTab] = useState<"plan" | "matrix" | "members">("plan");
  const [monthIndex, setMonthIndex] = useState<number | null>(null);
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["plan-group", id] });

  if (group.isLoading) return <Shell><p className="py-16 text-center text-sm text-muted-foreground">Loading group…</p></Shell>;
  if (group.isError || !group.data) {
    return <Shell><p className="py-16 text-center text-sm text-destructive">{group.error instanceof Error ? group.error.message : "Could not load the group."}</p></Shell>;
  }
  const data = group.data;
  // Defensive: the selected month may have been deleted in the months editor.
  const activeMonth = data.months.some((item) => item.month_index === monthIndex)
    ? monthIndex
    : data.months[0]?.month_index ?? null;

  async function setStatus(status: "draft" | "active" | "archived") {
    try {
      if (status === "archived") {
        const confirmation = await Swal.fire({
          icon: "warning", title: "Archive this group?",
          text: "Its plan stops appearing in journals. Progress is kept.",
          showCancelButton: true, confirmButtonText: "Archive", confirmButtonColor: "#dc2626",
        });
        if (!confirmation.isConfirmed) return;
        await archivePlanGroup(id);
      } else {
        await updatePlanGroup(id, { status });
      }
      await refresh();
      await queryClient.invalidateQueries({ queryKey: ["plan-groups"] });
      toast(status === "active" ? "Plan activated — it now appears in learner journals" : `Group ${status}`);
    } catch (cause) {
      fail("Could not change the status", cause);
    }
  }

  return (
    <Shell>
      <section className="rounded-lg border border-border bg-card shadow-panel">
        <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-7 py-5">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="font-serif text-lg text-foreground">{data.name}</h1>
              <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${data.status === "active" ? "bg-success/10 text-success" : data.status === "draft" ? "bg-warning/20 text-foreground ring-1 ring-warning/40" : "bg-muted text-muted-foreground"}`}>{data.status}</span>
            </div>
            <p className="mt-1 text-sm text-muted-foreground">
              {data.programme_name ?? "No programme"} · {data.members.length} members · {data.activities.filter((a) => a.included).length} activities
            </p>
          </div>
          <div className="flex items-center gap-2">
            {data.status !== "active" && <Button size="sm" onClick={() => void setStatus("active")}><Check className="mr-1 h-3.5 w-3.5" /> Activate plan</Button>}
            {data.status === "active" && <Button size="sm" variant="outline" onClick={() => void setStatus("draft")}>Back to draft</Button>}
            {data.status !== "archived" && <Button size="sm" variant="outline" onClick={() => void setStatus("archived")}><Trash2 className="mr-1 h-3.5 w-3.5" /> Archive</Button>}
          </div>
        </header>

        <nav className="flex gap-1 border-b border-border px-7 pt-3">
          {([["plan", "Plan"], ["matrix", "Progress matrix"], ["members", "Members"]] as const).map(([key, label]) => (
            <button
              key={key}
              type="button"
              onClick={() => setTab(key)}
              className={`rounded-t-md px-4 py-2 text-sm font-semibold transition-colors ${tab === key ? "border border-b-0 border-border bg-background text-foreground" : "text-muted-foreground hover:text-foreground"}`}
            >
              {label}
            </button>
          ))}
        </nav>

        {tab === "plan" && <PlanTab data={data} activeMonth={activeMonth} onMonth={setMonthIndex} refresh={refresh} />}
        {tab === "matrix" && <MatrixTab data={data} activeMonth={activeMonth} onMonth={setMonthIndex} />}
        {tab === "members" && <MembersTab data={data} refresh={refresh} />}
      </section>
    </Shell>
  );
}

function Shell({ children }: { children: React.ReactNode }) {
  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-[1700px] flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Plan builder</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <Link to="/groups" className="inline-flex items-center gap-1 font-medium hover:underline"><ArrowLeft className="h-3.5 w-3.5" /> Groups</Link>
            <Link to="/search" className="font-medium hover:underline">Learner search</Link>
            <Link to="/journal" search={{ learner: "", period: "" }} className="font-medium hover:underline">Monthly journal</Link>
          </div>
        </div>
      </header>
      <main className="mx-auto w-full max-w-[1700px] space-y-6 px-6 py-8">{children}</main>
    </div>
  );
}

// --- Plan tab -----------------------------------------------------------------

// A plan with no members applies to nobody — offer the one-click LMS-group
// assignment right where the auditor is building.
function AssignLearnersBanner({ data, refresh }: { data: PlanGroupDetail; refresh: () => Promise<unknown> | unknown }) {
  const queryClient = useQueryClient();
  const [saving, setSaving] = useState(false);
  const lmsGroups = useQuery({ queryKey: ["plan-lms-groups"], queryFn: pickLmsGroups });

  async function assign(lmsGroupId: string) {
    if (!lmsGroupId) return;
    setSaving(true);
    try {
      const seed = await pickLmsGroupMembers(Number(lmsGroupId));
      if (!seed.items.length) {
        void Swal.fire({ icon: "info", title: "Empty LMS group", text: "That LMS group has no Aptem-linked learners." });
        return;
      }
      const result = await updatePlanMembers(data.id, { add: seed.items.map((item) => item.aptem_id) });
      toast(`${result.added.length} learners assigned — everything you add now applies to all of them`);
      await Promise.all([
        refresh(),
        queryClient.invalidateQueries({ queryKey: ["plan-suggest", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-att-grid", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-assignments", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-materials", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-matrix", data.id] }),
      ]);
    } catch (cause) {
      fail("Could not assign the learners", cause);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="flex flex-wrap items-center gap-3 rounded-lg border border-warning/40 bg-warning/10 px-5 py-3">
      <UsersRound className="h-4 w-4 text-foreground" />
      <p className="text-sm font-medium text-foreground">
        No learners assigned yet — pick the LMS group and everyone in it joins this plan instantly:
      </p>
      <select className={`${field} max-w-72`} disabled={saving} defaultValue="" onChange={(e) => void assign(e.target.value)}>
        <option value="" disabled>Choose LMS group…</option>
        {(lmsGroups.data?.items ?? []).map((option) => (
          <option key={option.group_id} value={option.group_id}>{option.name} ({option.learner_count})</option>
        ))}
      </select>
    </div>
  );
}

function PlanTab({ data, activeMonth, onMonth, refresh }: {
  data: PlanGroupDetail; activeMonth: number | null;
  onMonth: (index: number) => void; refresh: () => Promise<unknown> | unknown;
}) {
  const queryClient = useQueryClient();
  const [picker, setPicker] = useState<null | { kind: string; weekSlot: number }>(null);
  const [editingMonths, setEditingMonths] = useState(false);
  const [ksbFor, setKsbFor] = useState<PlanActivity | null>(null);
  const [expandedKey, setExpandedKey] = useState<string | null>(null);
  // The month's matrix feeds the per-activity "who did it" counters and the
  // inline learner list — the plan view answers "حلّها ولا لأ" in place.
  const matrix = useQuery({
    queryKey: ["plan-matrix", data.id, activeMonth],
    queryFn: () => getPlanMatrix(data.id, activeMonth as number),
    enabled: activeMonth != null,
  });
  const matrixCells = matrix.data?.cells ?? {};
  const matrixMembers = matrix.data?.members ?? [];
  const refreshMatrix = () => queryClient.invalidateQueries({ queryKey: ["plan-matrix", data.id, activeMonth] });

  function activityStats(activity: PlanActivity) {
    const eligible = matrixMembers.filter((member) => !activity.exempted.includes(member.aptem_id));
    let confirmed = 0;
    let suggested = 0;
    for (const member of eligible) {
      const cell = matrixCells[`${member.aptem_id}:${activity.activity_key}`];
      if (cell?.progress && !cell.progress.rejected && cell.progress.status === "completed") confirmed += 1;
      else if (cell?.suggestion && (cell.suggestion.completed || cell.suggestion.attended)) suggested += 1;
    }
    return { confirmed, suggested, total: eligible.length };
  }

  async function quickSet(activity: PlanActivity, member: { aptem_id: number }, done: boolean) {
    const cell = matrixCells[`${member.aptem_id}:${activity.activity_key}`];
    const suggestion = cell?.suggestion;
    try {
      await savePlanProgress({
        aptem_id: member.aptem_id,
        activity_key: activity.activity_key,
        patch: done
          ? {
              status: "completed",
              actual_hours: suggestion?.actual_hours ?? activity.planned_hours,
              completion_date: suggestion?.date ?? activity.planned_date,
              ...(activity.category === "attendance" ? { attendance_status: "attended" as const } : {}),
              reading_viewed: suggestion?.reading_viewed ?? null,
              quiz_attempted: suggestion?.quiz_attempted ?? null,
              quiz_passed: suggestion?.quiz_passed ?? null,
              suggestion_accepted: Boolean(suggestion),
            }
          : {
              status: "not_started",
              actual_hours: 0,
              ...(activity.category === "attendance" ? { attendance_status: "absent" as const } : {}),
            },
      });
      await refreshMatrix();
    } catch (cause) {
      fail("Could not save", cause);
    }
  }

  async function confirmAllSuggested(activity: PlanActivity) {
    const todo = matrixMembers.filter((member) => {
      if (activity.exempted.includes(member.aptem_id)) return false;
      const cell = matrixCells[`${member.aptem_id}:${activity.activity_key}`];
      return !cell?.progress && cell?.suggestion && (cell.suggestion.completed || cell.suggestion.attended);
    });
    if (!todo.length) return;
    for (const member of todo) {
      // Each confirmation carries that learner's own suggested hours/date.
      // eslint-disable-next-line no-await-in-loop
      await quickSet(activity, member, true);
    }
    toast(`${todo.length} suggestions confirmed`);
  }
  const month = data.months.find((item) => item.month_index === activeMonth) ?? null;
  const monthActivities = data.activities
    .filter((item) => item.month_index === activeMonth && item.included)
    .sort((a, b) => a.week_slot - b.week_slot || (CATEGORY_ORDER[a.category] ?? 4) - (CATEGORY_ORDER[b.category] ?? 4) || a.position - b.position);
  const weeks = [1, 2, 3, 4, 5];

  async function exclude(activity: PlanActivity) {
    const confirmation = await Swal.fire({
      icon: "warning", title: "Remove from the plan?",
      text: "Recorded progress is kept (soft removal) and the row disappears from every member's journal.",
      showCancelButton: true, confirmButtonText: "Remove", confirmButtonColor: "#dc2626",
    });
    if (!confirmation.isConfirmed) return;
    try {
      const result = await excludePlanActivity(activity.activity_key);
      warnSigned(result.signed_warnings);
      await refresh();
      toast(result.progress_rows_kept > 0 ? `Removed — ${result.progress_rows_kept} progress records kept` : "Removed from the plan");
    } catch (cause) {
      fail("Could not remove the activity", cause);
    }
  }

  async function editActivity(activity: PlanActivity) {
    const { value: formValues } = await Swal.fire({
      title: "Edit activity",
      html:
        `<input id="plan-edit-title" class="swal2-input" style="width:85%" value="${esc(activity.title)}" placeholder="Title">` +
        `<input id="plan-edit-hours" type="number" min="0" max="50" step="0.25" class="swal2-input" style="width:40%" value="${esc(activity.planned_hours)}" placeholder="Planned hours">` +
        `<input id="plan-edit-date" type="date" class="swal2-input" style="width:40%" value="${esc(activity.planned_date ?? "")}">`,
      focusConfirm: false, showCancelButton: true, confirmButtonText: "Save",
      preConfirm: () => ({
        title: (document.getElementById("plan-edit-title") as HTMLInputElement).value,
        planned_hours: Number((document.getElementById("plan-edit-hours") as HTMLInputElement).value),
        planned_date: (document.getElementById("plan-edit-date") as HTMLInputElement).value || null,
      }),
    });
    if (!formValues) return;
    try {
      const result = await patchPlanActivity(activity.activity_key, formValues);
      warnSigned(result.signed_warnings);
      await refresh();
      toast("Activity updated for the whole group");
    } catch (cause) {
      fail("Could not update the activity", cause);
    }
  }

  return (
    <div className="space-y-5 px-7 py-6">
      {data.members.length === 0 && <AssignLearnersBanner data={data} refresh={refresh} />}
      <div className="flex flex-wrap items-center gap-2">
        {data.months.map((item) => (
          <button
            key={item.month_index}
            type="button"
            onClick={() => onMonth(item.month_index)}
            className={`rounded-full px-3 py-1.5 text-xs font-semibold transition-colors ${item.month_index === activeMonth ? "bg-[#182d48] text-white" : "bg-secondary text-muted-foreground hover:text-foreground"}`}
          >
            M{item.month_index} · {item.label}
          </button>
        ))}
        <Button size="sm" variant="outline" onClick={() => setEditingMonths(true)}>
          <CalendarDays className="mr-1 h-3.5 w-3.5" /> Edit months
        </Button>
      </div>

      {!month && <p className="py-10 text-center text-sm text-muted-foreground">Add months to the schedule first (Edit months).</p>}

      {month && weeks.map((week) => {
        const weekActivities = monthActivities.filter((item) => item.week_slot === week);
        return (
          <div key={week} className="rounded-lg border border-border">
            <header className="flex items-center justify-between border-b border-border bg-[#eef3f8] px-5 py-2.5">
              <span className="text-xs font-semibold uppercase tracking-wider text-[#182d48]">Week {week} — {month.label}</span>
              <AddMenu onPick={(kind) => setPicker({ kind, weekSlot: week })} />
            </header>
            {weekActivities.length === 0 ? (
              <p className="px-5 py-4 text-xs text-muted-foreground">Nothing planned this week yet.</p>
            ) : (
              <ul className="divide-y divide-border">
                {weekActivities.map((activity) => {
                  const stats = activityStats(activity);
                  const isExpanded = expandedKey === activity.activity_key;
                  return (
                    <li key={activity.activity_key} className="px-5 py-3">
                      <div className="flex flex-wrap items-center gap-3">
                        <span className={`rounded-full px-2 py-0.5 text-[11px] font-semibold ${categoryChip(activity.category)}`}>{activity.category}</span>
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-medium text-foreground">{activity.title}</p>
                          <p className="text-xs text-muted-foreground">
                            {activity.planned_hours} h
                            {activity.planned_date ? ` · ${activity.planned_date}` : ""}
                            {activity.material_ref ? ` · ${activity.material_ref}` : " · manual"}
                            {activity.exempted.length > 0 ? ` · ${activity.exempted.length} exempted` : ""}
                          </p>
                        </div>
                        {/* "who did it" counter: solid = confirmed, ghost = the
                            data says done but awaits the auditor's confirm. */}
                        <button
                          type="button"
                          onClick={() => setExpandedKey(isExpanded ? null : activity.activity_key)}
                          title="Show every learner's status"
                          className={`rounded-full px-2.5 py-1 font-mono text-[11px] font-semibold transition-colors ${isExpanded ? "bg-[#182d48] text-white" : "bg-secondary text-foreground hover:bg-[#eef3f8]"}`}
                        >
                          ✓ {stats.confirmed}/{stats.total}{stats.suggested > 0 ? ` · ✓? ${stats.suggested}` : ""}
                        </button>
                        <button type="button" title="KSBs" onClick={() => setKsbFor(activity)} className="rounded p-1.5 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground">
                          <Tags className="h-4 w-4" />
                          {(activity.ksbs?.K?.length ?? 0) + (activity.ksbs?.S?.length ?? 0) + (activity.ksbs?.B?.length ?? 0) > 0 && (
                            <span className="ml-0.5 align-middle text-[10px] font-semibold">{(activity.ksbs?.K?.length ?? 0) + (activity.ksbs?.S?.length ?? 0) + (activity.ksbs?.B?.length ?? 0)}</span>
                          )}
                        </button>
                        <button type="button" title="Edit" onClick={() => void editActivity(activity)} className="rounded p-1.5 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground"><Pencil className="h-4 w-4" /></button>
                        <button type="button" title="Remove" onClick={() => void exclude(activity)} className="rounded p-1.5 text-destructive transition-colors hover:bg-destructive/10"><Trash2 className="h-4 w-4" /></button>
                      </div>
                      {isExpanded && (
                        <div className="mt-3 rounded-lg border border-border bg-[#f7f9fc] px-4 py-3">
                          <div className="mb-2 flex items-center justify-between">
                            <span className="text-xs font-semibold text-[#182d48]">Learners — did they do it?</span>
                            {stats.suggested > 0 && (
                              <Button size="sm" variant="outline" onClick={() => void confirmAllSuggested(activity)}>
                                <Check className="mr-1 h-3.5 w-3.5" /> Confirm all suggested ({stats.suggested})
                              </Button>
                            )}
                          </div>
                          <ul className="grid gap-1 sm:grid-cols-2 lg:grid-cols-3">
                            {matrixMembers
                              .filter((member) => !activity.exempted.includes(member.aptem_id))
                              .map((member) => {
                                const cell = matrixCells[`${member.aptem_id}:${activity.activity_key}`];
                                const progress = cell?.progress && !cell.progress.rejected ? cell.progress : null;
                                const suggestion = cell?.suggestion;
                                const done = progress?.status === "completed";
                                const suggestedDone = !progress && suggestion && (suggestion.completed || suggestion.attended);
                                return (
                                  <li key={member.aptem_id} className="flex items-center gap-2 rounded-md bg-card px-2.5 py-1.5 text-xs">
                                    <span className={`font-bold ${done ? "text-success" : suggestedDone ? "text-amber-600" : "text-muted-foreground"}`}>
                                      {done ? "✓" : suggestedDone ? "✓?" : "✗"}
                                    </span>
                                    <span className="min-w-0 flex-1 truncate font-medium text-foreground" title={member.name ?? String(member.aptem_id)}>
                                      {member.name ?? member.aptem_id}
                                    </span>
                                    {done ? (
                                      <button type="button" onClick={() => void quickSet(activity, member, false)} className="rounded border border-border px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-secondary">undo</button>
                                    ) : (
                                      <button type="button" onClick={() => void quickSet(activity, member, true)} className="rounded border border-success/40 bg-success/10 px-1.5 py-0.5 text-[10px] font-semibold text-success hover:bg-success/20">
                                        {suggestedDone ? "confirm" : "done"}
                                      </button>
                                    )}
                                  </li>
                                );
                              })}
                          </ul>
                        </div>
                      )}
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        );
      })}

      {picker && month && (
        <PickerModal
          data={data}
          month={month}
          weekSlot={picker.weekSlot}
          kind={picker.kind}
          onClose={() => setPicker(null)}
          onDone={async () => { setPicker(null); await refresh(); }}
        />
      )}
      {editingMonths && (
        <MonthsEditor data={data} onClose={() => setEditingMonths(false)} onDone={async () => { setEditingMonths(false); await refresh(); }} />
      )}
      {ksbFor && (
        <KsbEditor activity={ksbFor} onClose={() => setKsbFor(null)} onDone={async () => { setKsbFor(null); await refresh(); }} />
      )}
    </div>
  );
}

function AddMenu({ onPick }: { onPick: (kind: string) => void }) {
  const [open, setOpen] = useState(false);
  return (
    <span className="relative">
      <Button size="sm" variant="outline" onClick={() => setOpen((value) => !value)}>
        <Plus className="mr-1 h-3.5 w-3.5" /> Add
      </Button>
      {open && (
        <span className="absolute right-0 top-9 z-20 block w-56 rounded-md border border-border bg-card py-1 shadow-panel">
          {ADD_MENU.map((item) => (
            <button
              key={item.category}
              type="button"
              onClick={() => { setOpen(false); onPick(item.category); }}
              className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm text-foreground hover:bg-secondary"
            >
              <item.icon className="h-4 w-4 text-muted-foreground" /> {item.label}
            </button>
          ))}
        </span>
      )}
    </span>
  );
}

// --- Picker modal ---------------------------------------------------------------

function Modal({ title, onClose, children, wide = false }: {
  title: string; onClose: () => void; children: React.ReactNode; wide?: boolean;
}) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <div
        className={`max-h-[85vh] w-full ${wide ? "max-w-4xl" : "max-w-2xl"} overflow-auto rounded-lg border border-border bg-card shadow-panel`}
        onClick={(event) => event.stopPropagation()}
      >
        <header className="sticky top-0 flex items-center justify-between border-b border-border bg-card px-6 py-4">
          <h2 className="font-serif text-base text-foreground">{title}</h2>
          <button type="button" onClick={onClose} className="rounded p-1.5 text-muted-foreground hover:bg-secondary"><X className="h-4 w-4" /></button>
        </header>
        <div className="px-6 py-4">{children}</div>
      </div>
    </div>
  );
}

function PickerModal({ data, month, weekSlot, kind, onClose, onDone }: {
  data: PlanGroupDetail; month: { month_index: number; calendar_month: string; label: string };
  weekSlot: number; kind: string; onClose: () => void; onDone: () => Promise<void>;
}) {
  const [saving, setSaving] = useState(false);

  async function add(activities: Parameters<typeof addPlanActivities>[0]["activities"], assignmentRefs?: Parameters<typeof addPlanActivities>[0]["assignment_refs"]) {
    setSaving(true);
    try {
      const result = await addPlanActivities({ group_id: data.id, activities, assignment_refs: assignmentRefs });
      if (result.duplicate_refs.length) {
        void Swal.fire({ icon: "info", title: "Already in the plan", text: `${result.duplicate_refs.length} of the selected items were already planned — they were added again on purpose only if you selected them twice.` });
      }
      warnSigned(result.signed_warnings);
      toast(`${result.activity_keys.length} added to Week ${weekSlot}`);
      await onDone();
    } catch (cause) {
      fail("Could not add to the plan", cause);
    } finally {
      setSaving(false);
    }
  }

  if (kind === "attendance") {
    return <AttendancePicker data={data} month={month} weekSlot={weekSlot} saving={saving} onAdd={add} onClose={onClose} />;
  }
  if (kind === "video" || kind === "reading+quiz" || kind === "audio") {
    return <MaterialsPicker data={data} month={month} weekSlot={weekSlot} type={kind} saving={saving} onAdd={add} onClose={onClose} />;
  }
  if (kind === "assignment") {
    return <AssignmentPicker data={data} month={month} weekSlot={weekSlot} saving={saving} onAdd={add} onClose={onClose} />;
  }
  return <ManualPicker month={month} weekSlot={weekSlot} saving={saving} onAdd={add} onClose={onClose} />;
}

function AttendancePicker({ data, month, weekSlot, saving, onAdd, onClose }) {
  const queryClient = useQueryClient();
  // The whole cohort by default — the auditor searches and selects from the
  // full bulk sheet (rows = learners, columns = session days).
  const [showAll, setShowAll] = useState(true);
  const [search, setSearch] = useState("");
  const [learnerSearch, setLearnerSearch] = useState("");
  const [selected, setSelected] = useState<Record<string, boolean>>({});
  const [selectedLearners, setSelectedLearners] = useState<Record<number, boolean>>({});
  const [addingLearners, setAddingLearners] = useState(false);
  const grid = useQuery({
    queryKey: ["plan-att-grid", data.id, month.calendar_month, showAll],
    queryFn: () => pickAttendanceGrid(data.id, month.calendar_month, showAll),
  });

  const needle = search.trim().toLowerCase();
  const days = (grid.data?.days ?? []).filter(
    (day) => !needle || day.module.toLowerCase().includes(needle) || day.date.includes(needle),
  );
  const learnerNeedle = learnerSearch.trim().toLowerCase();
  const learners = (grid.data?.learners ?? []).filter(
    (item) => !learnerNeedle
      || String(item.name ?? "").toLowerCase().includes(learnerNeedle)
      || String(item.aptem_id).includes(learnerNeedle),
  );
  const cells = grid.data?.cells ?? {};
  const chosen = days.filter((day) => selected[day.session_ref]);
  const allVisibleSelected = days.length > 0 && days.every((day) => selected[day.session_ref]);
  const chosenLearners = learners.filter((item) => !item.is_member && selectedLearners[item.aptem_id]);

  // Selecting learners straight from the bulk sheet adds them to the group —
  // the plan (and everything added next) then applies to them too.
  async function addSelectedLearners() {
    setAddingLearners(true);
    try {
      const result = await updatePlanMembers(data.id, { add: chosenLearners.map((item) => item.aptem_id) });
      setSelectedLearners({});
      toast(`${result.added.length} learners added to the group`);
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ["plan-group", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-att-grid", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-suggest", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-assignments", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-materials", data.id] }),
        queryClient.invalidateQueries({ queryKey: ["plan-matrix", data.id] }),
      ]);
    } catch (cause) {
      fail("Could not add the learners", cause);
    } finally {
      setAddingLearners(false);
    }
  }

  return (
    <Modal title={`Attendance sheet — ${month.label}`} onClose={onClose} wide>
      <div className="mb-3 flex flex-wrap items-center gap-3">
        <input className={`${field} max-w-52`} placeholder="Search learner…" value={learnerSearch} onChange={(e) => setLearnerSearch(e.target.value)} />
        <input className={`${field} max-w-52`} placeholder="Search session / date…" value={search} onChange={(e) => setSearch(e.target.value)} />
        <label className="flex items-center gap-2 text-xs text-muted-foreground">
          <input type="checkbox" checked={showAll} onChange={(e) => setShowAll(e.target.checked)} />
          Whole cohort
        </label>
        <label className="flex items-center gap-2 text-xs text-muted-foreground">
          <input
            type="checkbox"
            checked={allVisibleSelected}
            onChange={(e) => setSelected((current) => {
              const next = { ...current };
              for (const day of days) next[day.session_ref] = e.target.checked;
              return next;
            })}
          />
          Select all days
        </label>
        <span className="flex-1" />
        {chosenLearners.length > 0 && (
          <Button size="sm" variant="outline" disabled={addingLearners} onClick={() => void addSelectedLearners()}>
            <UsersRound className="mr-1 h-3.5 w-3.5" /> Add {chosenLearners.length} to group
          </Button>
        )}
        <Button size="sm" disabled={saving || chosen.length === 0} onClick={() => void onAdd(chosen.map((day) => ({
          category: "attendance",
          title: day.module,
          month_index: month.month_index,
          week_slot: weekSlot,
          material_ref: day.session_ref,
          planned_hours: day.default_hours,
          planned_date: day.date,
        })))}>Add {chosen.length || ""} selected day{chosen.length === 1 ? "" : "s"}</Button>
      </div>
      {grid.isLoading && <p className="py-8 text-center text-sm text-muted-foreground">Loading the attendance sheet…</p>}
      {!grid.isLoading && days.length === 0 && (
        <p className="py-8 text-center text-sm text-muted-foreground">
          No attendance sessions recorded in {month.label}{needle ? " matching the search" : ""} — add a planned day manually (Add → Manual activity) and it will link when the data syncs.
        </p>
      )}
      {days.length > 0 && (
        <div className="max-h-[60vh] overflow-auto rounded-lg border border-border">
          <table className="w-full min-w-[700px] border-collapse text-xs">
            <thead className="sticky top-0 z-10">
              <tr className="bg-[#182d48] text-white">
                <th className="sticky left-0 z-20 bg-[#182d48] px-3 py-2 text-left font-semibold">Learner</th>
                {days.map((day) => (
                  <th key={day.session_ref} className={`min-w-24 max-w-32 px-2 py-2 text-left align-bottom font-medium ${selected[day.session_ref] ? "bg-[#2a4a73]" : ""}`}>
                    <label className="flex cursor-pointer flex-col gap-1">
                      <span className="flex items-center gap-1.5">
                        <input
                          type="checkbox"
                          checked={!!selected[day.session_ref]}
                          onChange={(e) => setSelected((s) => ({ ...s, [day.session_ref]: e.target.checked }))}
                        />
                        <span className="font-mono">{day.date.slice(8, 10)}/{day.date.slice(5, 7)}</span>
                      </span>
                      <span className="block truncate text-[10px] font-normal text-white/80" title={day.module}>{day.module}</span>
                      <span className="text-[10px] font-normal text-white/60">{day.default_hours} h</span>
                    </label>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {learners.map((learner) => (
                <tr key={learner.aptem_id} className="odd:bg-[#f7f9fc]">
                  <td className="sticky left-0 z-10 max-w-64 bg-inherit px-3 py-1.5 font-medium text-foreground" title={learner.name ?? String(learner.aptem_id)}>
                    <span className="flex items-center gap-2">
                      {learner.is_member ? (
                        <span className="rounded bg-success/10 px-1 py-0.5 text-[9px] font-semibold text-success" title="In this group">✓</span>
                      ) : (
                        <input
                          type="checkbox"
                          title="Select to add this learner to the group"
                          checked={!!selectedLearners[learner.aptem_id]}
                          onChange={(e) => setSelectedLearners((s) => ({ ...s, [learner.aptem_id]: e.target.checked }))}
                        />
                      )}
                      <span className="truncate">{learner.name ?? learner.aptem_id}</span>
                    </span>
                  </td>
                  {days.map((day) => {
                    const cell = cells[`${learner.aptem_id}:${day.session_ref}`];
                    return (
                      <td key={day.session_ref} className={`px-2 py-1.5 text-center ${selected[day.session_ref] ? "bg-[#eef3f8]" : ""}`}>
                        {cell == null ? (
                          <span className="text-muted-foreground/50">·</span>
                        ) : cell.attended ? (
                          <span className="font-bold text-success" title={`Attended${cell.hours != null ? ` · ${cell.hours} h` : ""}`}>✓</span>
                        ) : (
                          <span className="font-bold text-destructive" title="Absent">✗</span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
              <tr className="border-t border-border bg-[#eef3f8]">
                <td className="sticky left-0 z-10 bg-[#eef3f8] px-3 py-1.5 font-semibold text-[#182d48]">Attended (yours)</td>
                {days.map((day) => (
                  <td key={day.session_ref} className="px-2 py-1.5 text-center font-mono font-semibold text-[#182d48]">
                    {day.member_attended}/{day.member_rows}
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
      )}
      <p className="mt-2 text-xs text-muted-foreground">
        ✓ attended · ✗ absent · &nbsp;·&nbsp; no record. Tick the day columns you want, then Add — each day becomes one attendance activity for the whole group (date from the session, editable afterwards).
      </p>
    </Modal>
  );
}

function MaterialsPicker({ data, month, weekSlot, type, saving, onAdd, onClose }) {
  const [scope, setScope] = useState<"group" | "all">("group");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<Record<string, MaterialOption>>({});
  const materials = useQuery({
    queryKey: ["plan-materials", data.id, type, scope, search],
    queryFn: () => pickMaterials({ groupId: data.id, type, scope, search: search || undefined, limit: 60 }),
  });
  const items = materials.data?.items ?? [];
  const chosen = Object.values(selected);

  return (
    <Modal title={`${type === "video" ? "Videos / recordings" : type === "audio" ? "Audio" : "Reading + Quiz"} — Week ${weekSlot}`} onClose={onClose} wide>
      <div className="mb-3 flex flex-wrap items-center gap-2">
        <div className="flex rounded-md border border-border">
          {(["group", "all"] as const).map((value) => (
            <button key={value} type="button" onClick={() => setScope(value)}
              className={`px-3 py-1.5 text-xs font-semibold ${scope === value ? "bg-[#182d48] text-white" : "text-muted-foreground"}`}>
              {value === "group" ? "This group's materials" : "Full catalogue"}
            </button>
          ))}
        </div>
        <input className={`${field} max-w-xs`} placeholder="Search title…" value={search} onChange={(e) => setSearch(e.target.value)} />
        <span className="flex-1" />
        <Button size="sm" disabled={saving || chosen.length === 0} onClick={() => void onAdd(chosen.map((item) => ({
          category: type,
          title: item.title,
          month_index: month.month_index,
          week_slot: weekSlot,
          material_ref: item.material_ref,
          planned_hours: item.suggested_hours ?? 0,
        })))}>Add {chosen.length || ""} selected</Button>
      </div>
      {materials.isLoading && <p className="py-8 text-center text-sm text-muted-foreground">Loading materials…</p>}
      <ul className="divide-y divide-border">
        {items.map((item) => (
          <li key={item.material_ref} className="flex items-center gap-3 py-2.5">
            <input type="checkbox" checked={!!selected[item.material_ref]} onChange={(e) => setSelected((s) => {
              const next = { ...s };
              if (e.target.checked) next[item.material_ref] = item; else delete next[item.material_ref];
              return next;
            })} />
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium text-foreground">{item.title}</p>
              <p className="font-mono text-xs text-muted-foreground">
                lms:{item.activity_id}{item.suggested_hours ? ` · ~${item.suggested_hours} h` : ""}{scope === "group" ? ` · ${item.engaged_members} of yours engaged` : ""}
              </p>
            </div>
            <span className="flex gap-1">
              {item.has_iframe && <span className="rounded bg-[#e5f3ef] px-1.5 py-0.5 text-[10px] font-semibold text-[#16856b]">iframe</span>}
              {item.has_text && <span className="rounded bg-secondary px-1.5 py-0.5 text-[10px] font-semibold text-muted-foreground">text</span>}
              {item.has_quiz && <span className="rounded bg-[#fbf0df] px-1.5 py-0.5 text-[10px] font-semibold text-[#8a5a10]">quiz</span>}
            </span>
          </li>
        ))}
      </ul>
    </Modal>
  );
}

function AssignmentPicker({ data, month, weekSlot, saving, onAdd, onClose }) {
  const assignments = useQuery({ queryKey: ["plan-assignments", data.id], queryFn: () => pickAssignments(data.id) });
  const items = assignments.data?.items ?? [];
  const monthAssignments = data.activities.filter((a) => a.included && a.category === "assignment" && a.month_index === month.month_index);

  async function pick(option: AssignmentOption) {
    if (monthAssignments.length > 0) {
      const confirmation = await Swal.fire({
        icon: "warning",
        title: `This would be assignment ${monthAssignments.length + 1} this month`,
        text: "Usually one assignment per month (last week). Add anyway?",
        showCancelButton: true, confirmButtonText: "Add anyway",
      });
      if (!confirmation.isConfirmed) return;
    }
    await onAdd(
      [{
        category: "assignment",
        title: option.name,
        month_index: month.month_index,
        week_slot: weekSlot,
        material_ref: option.material_ref,
        planned_hours: option.suggested_hours ?? 0,
      }],
      option.learners.map((learner) => ({
        aptem_id: learner.aptem_id,
        component_id: learner.component_id,
        component_name: learner.component_name,
        assignment_month: learner.assignment_month,
      })),
    );
  }

  return (
    <Modal title={`Assignments — ${month.label}`} onClose={onClose} wide>
      {assignments.isLoading && <p className="py-8 text-center text-sm text-muted-foreground">Loading assignments…</p>}
      {!assignments.isLoading && items.length === 0 && <p className="py-8 text-center text-sm text-muted-foreground">No Aptem assignments found for this group&apos;s members.</p>}
      <ul className="divide-y divide-border">
        {items.map((item) => (
          <li key={item.name_key} className="flex items-center gap-3 py-2.5">
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium text-foreground">{item.name}</p>
              <p className="text-xs text-muted-foreground">
                {item.learner_count} of your members ·
                {Object.entries(item.month_counts).slice(0, 4).map(([m, c]) => ` due ${m}: ${c}`).join(" ·")}
              </p>
              <p className="text-xs text-muted-foreground">
                {Object.entries(item.status_counts).map(([status, count]) => `${status}: ${count}`).join(" · ")}
              </p>
            </div>
            <Button size="sm" variant="outline" disabled={saving} onClick={() => void pick(item)}>Add</Button>
          </li>
        ))}
      </ul>
    </Modal>
  );
}

function ManualPicker({ month, weekSlot, saving, onAdd, onClose }) {
  const [category, setCategory] = useState("attendance");
  const [title, setTitle] = useState("");
  const [hours, setHours] = useState(0);
  const [date, setDate] = useState("");
  return (
    <Modal title={`Manual activity — Week ${weekSlot}, ${month.label}`} onClose={onClose}>
      <div className="space-y-3">
        <label className="block">
          <span className="label-caps">Category</span>
          <select className={`${field} mt-1.5`} value={category} onChange={(e) => setCategory(e.target.value)}>
            {["attendance", "video", "reading+quiz", "audio", "assignment"].map((option) => <option key={option} value={option}>{option}</option>)}
          </select>
        </label>
        <label className="block">
          <span className="label-caps">Title</span>
          <input className={`${field} mt-1.5`} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Face to face workshop" />
        </label>
        <div className="grid grid-cols-2 gap-3">
          <label className="block">
            <span className="label-caps">Planned hours</span>
            <input type="number" min={0} max={50} step={0.25} className={`${field} mt-1.5`} value={hours} onChange={(e) => setHours(Number(e.target.value) || 0)} />
          </label>
          <label className="block">
            <span className="label-caps">Date (optional)</span>
            <input type="date" className={`${field} mt-1.5`} value={date} onChange={(e) => setDate(e.target.value)} />
          </label>
        </div>
        <Button size="sm" disabled={saving || !title.trim()} onClick={() => void onAdd([{
          category, title: title.trim(), month_index: month.month_index, week_slot: weekSlot,
          planned_hours: hours, planned_date: date || null,
        }])}>Add to plan</Button>
      </div>
    </Modal>
  );
}

// --- Months editor ---------------------------------------------------------------

function MonthsEditor({ data, onClose, onDone }: { data: PlanGroupDetail; onClose: () => void; onDone: () => Promise<void> }) {
  const [rows, setRows] = useState(data.months.length ? data.months.map((m) => ({ ...m })) : [{ month_index: 1, calendar_month: "", label: "", anchor_date: null }]);
  const [saving, setSaving] = useState(false);

  async function save() {
    setSaving(true);
    try {
      await updatePlanMonths(data.id, rows.filter((row) => row.calendar_month));
      toast("Months updated");
      await onDone();
    } catch (cause) {
      fail("Could not save the months", cause);
    } finally {
      setSaving(false);
    }
  }

  return (
    <Modal title="Group months (a break month? just skip it)" onClose={onClose}>
      <div className="space-y-2">
        {rows.map((row, index) => (
          <div key={index} className="flex items-center gap-2">
            <span className="w-10 font-mono text-xs text-muted-foreground">M{row.month_index}</span>
            <input type="month" className={`${field} max-w-44`} value={row.calendar_month} onChange={(e) => setRows((r) => r.map((item, i) => i === index ? { ...item, calendar_month: e.target.value } : item))} />
            <input type="date" title="Week 1 anchor (optional)" className={`${field} max-w-44`} value={row.anchor_date ?? ""} onChange={(e) => setRows((r) => r.map((item, i) => i === index ? { ...item, anchor_date: e.target.value || null } : item))} />
          </div>
        ))}
        <div className="flex items-center gap-2 pt-2">
          <Button size="sm" variant="outline" onClick={() => setRows((r) => [...r, { month_index: (r[r.length - 1]?.month_index ?? 0) + 1, calendar_month: "", label: "", anchor_date: null }])}>
            <Plus className="mr-1 h-3.5 w-3.5" /> Add month
          </Button>
          <Button size="sm" disabled={saving} onClick={() => void save()}>Save months</Button>
        </div>
      </div>
    </Modal>
  );
}

// --- KSB editor ---------------------------------------------------------------

function KsbEditor({ activity, onClose, onDone }: { activity: PlanActivity; onClose: () => void; onDone: () => Promise<void> }) {
  const [standard, setStandard] = useState("");
  const [selected, setSelected] = useState<PlanKsbs>(activity.ksbs ?? { K: [], S: [], B: [] });
  const [saving, setSaving] = useState(false);
  const catalogue = useQuery({ queryKey: ["plan-ksbs", standard], queryFn: () => pickKsbs(standard || undefined) });

  function toggle(bucket: "K" | "S" | "B", code: string, description?: string | null) {
    setSelected((current) => {
      const list = current[bucket] ?? [];
      const exists = list.some((item) => item.code === code);
      return {
        ...current,
        [bucket]: exists ? list.filter((item) => item.code !== code) : [...list, { code, description }],
      };
    });
  }

  async function save() {
    setSaving(true);
    try {
      await patchPlanActivity(activity.activity_key, { ksbs: selected });
      toast("KSBs saved");
      await onDone();
    } catch (cause) {
      fail("Could not save the KSBs", cause);
    } finally {
      setSaving(false);
    }
  }

  const chosenCount = (selected.K?.length ?? 0) + (selected.S?.length ?? 0) + (selected.B?.length ?? 0);
  return (
    <Modal title={`KSBs — ${activity.title}`} onClose={onClose} wide>
      <div className="mb-3 flex items-center gap-2">
        <select className={`${field} max-w-md`} value={standard} onChange={(e) => setStandard(e.target.value)}>
          <option value="">All standards</option>
          {(catalogue.data?.standards ?? []).map((option) => <option key={option} value={option}>{option}</option>)}
        </select>
        <span className="flex-1" />
        <span className="text-xs text-muted-foreground">{chosenCount} selected</span>
        <Button size="sm" disabled={saving} onClick={() => void save()}><ListChecks className="mr-1 h-3.5 w-3.5" /> Save</Button>
      </div>
      {(["K", "S", "B"] as const).map((bucket) => (
        <div key={bucket} className="mb-4">
          <p className="label-caps mb-2">{bucket === "K" ? "Knowledge" : bucket === "S" ? "Skills" : "Behaviours"}</p>
          <ul className="grid gap-1 sm:grid-cols-2">
            {(catalogue.data?.ksbs[bucket] ?? []).map((item) => {
              const active = (selected[bucket] ?? []).some((chosen) => chosen.code === item.code);
              return (
                <li key={item.code}>
                  <button type="button" onClick={() => toggle(bucket, item.code, item.description)}
                    className={`w-full rounded-md border px-2.5 py-1.5 text-left text-xs transition-colors ${active ? "border-[#182d48] bg-[#eef3f8] text-[#182d48]" : "border-border text-muted-foreground hover:bg-secondary"}`}>
                    <span className="font-semibold">{item.code}</span> — {(item.description ?? "").slice(0, 90)}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      ))}
    </Modal>
  );
}

// --- Matrix tab ---------------------------------------------------------------

function AssignmentEvidenceModal({ data, activity, onClose }: {
  data: PlanGroupDetail; activity: { title: string; material_ref: string | null }; onClose: () => void;
}) {
  const nameKey = (activity.material_ref ?? "").startsWith("asg:") ? activity.material_ref!.slice(4) : "";
  const evidence = useQuery({
    queryKey: ["plan-asg-evidence", data.id, nameKey],
    queryFn: () => pickAssignmentEvidence(data.id, nameKey),
    enabled: Boolean(nameKey),
  });
  return (
    <Modal title={`Evidence — ${activity.title}`} onClose={onClose} wide>
      {evidence.isLoading && <p className="py-8 text-center text-sm text-muted-foreground">Loading evidence…</p>}
      <ul className="divide-y divide-border">
        {(evidence.data?.items ?? []).map((learner) => (
          <li key={learner.aptem_id} className="py-3">
            <p className="text-sm font-semibold text-foreground">{learner.name ?? learner.aptem_id}</p>
            {learner.documents.length === 0 ? (
              <p className="mt-1 text-xs text-muted-foreground">No submitted document fetched yet.</p>
            ) : (
              <ul className="mt-1 space-y-1">
                {learner.documents.map((doc) => (
                  <li key={doc.evidence_id} className="flex flex-wrap items-center gap-2 text-xs">
                    <FileText className="h-3.5 w-3.5 text-muted-foreground" />
                    <span className="min-w-0 flex-1 truncate text-foreground">{doc.name ?? `Evidence ${doc.evidence_id}`}</span>
                    <span className="text-muted-foreground">{doc.status ?? ""} {doc.submission_date ? `· ${doc.submission_date}` : ""}</span>
                    {doc.open_url ? (
                      <a href={doc.open_url} target="_blank" rel="noreferrer" className="rounded-md border border-border px-2 py-0.5 font-semibold text-foreground hover:bg-secondary">Preview</a>
                    ) : doc.aptem_url ? (
                      <a href={doc.aptem_url} target="_blank" rel="noreferrer" className="rounded-md border border-border px-2 py-0.5 text-muted-foreground hover:bg-secondary">Open in Aptem</a>
                    ) : null}
                  </li>
                ))}
              </ul>
            )}
          </li>
        ))}
      </ul>
    </Modal>
  );
}

function MatrixTab({ data, activeMonth, onMonth }: {
  data: PlanGroupDetail; activeMonth: number | null; onMonth: (index: number) => void;
}) {
  const queryClient = useQueryClient();
  const [evidenceFor, setEvidenceFor] = useState<null | { title: string; material_ref: string | null }>(null);
  const matrix = useQuery({
    queryKey: ["plan-matrix", data.id, activeMonth],
    queryFn: () => getPlanMatrix(data.id, activeMonth as number),
    enabled: activeMonth != null,
  });
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["plan-matrix", data.id, activeMonth] });

  async function editCell(member, activity, cell) {
    const progress = cell?.progress;
    const suggestion = cell?.suggestion;
    const isAttendance = activity.category === "attendance";
    const { value: action } = await Swal.fire({
      titleText: String(member.name ?? member.aptem_id),
      html: `<p style="font-size:13px;color:#64748b">${esc(activity.title)}</p>` + (suggestion && !progress
        ? `<p style="font-size:12px;color:#b45309;margin-top:6px">Suggested from data: ${esc(suggestion.kind === "attendance" ? (suggestion.attended ? "attended" : "absent") : suggestion.completed ? "completed" : suggestion.status ?? "seen")}${suggestion.actual_hours != null ? ` · ${esc(suggestion.actual_hours)} h` : ""}</p>`
        : ""),
      input: "select",
      inputOptions: isAttendance
        ? { attended: "Attended", makeup: "Makeup", absent: "Absent", clear: "Clear (back to suggested)" }
        : { completed: "Completed (actual = planned)", not_accepted: "Not accepted", not_started: "Not started", clear: "Clear (back to suggested)" },
      inputValue: progress ? (isAttendance ? progress.attendance_status ?? "attended" : progress.status) : (suggestion?.attended || suggestion?.completed ? (isAttendance ? "attended" : "completed") : ""),
      showCancelButton: true,
      confirmButtonText: "Save",
    });
    if (!action) return;
    try {
      if (action === "clear") {
        const { clearPlanProgress } = await import("@/features/audit/learner-log-pro-manual/lib/plan-api");
        await clearPlanProgress(member.aptem_id, activity.activity_key);
      } else if (isAttendance) {
        const result = await savePlanProgress({
          aptem_id: member.aptem_id, activity_key: activity.activity_key,
          patch: {
            status: action === "absent" ? "not_started" : "completed",
            attendance_status: action,
            actual_hours: action === "absent" ? 0 : (suggestion?.actual_hours ?? activity.planned_hours),
            completion_date: activity.planned_date,
            suggestion_accepted: !!suggestion,
          },
        });
        warnSigned(result.signed_warnings);
      } else {
        const result = await savePlanProgress({
          aptem_id: member.aptem_id, activity_key: activity.activity_key,
          patch: {
            status: action,
            actual_hours: action === "completed" ? (suggestion?.actual_hours ?? activity.planned_hours) : 0,
            completion_date: action === "completed" ? (suggestion?.date ?? activity.planned_date) : null,
            reading_viewed: suggestion?.reading_viewed ?? null,
            quiz_attempted: suggestion?.quiz_attempted ?? null,
            quiz_passed: suggestion?.quiz_passed ?? null,
            suggestion_accepted: !!suggestion,
          },
        });
        warnSigned(result.signed_warnings);
      }
      await refresh();
    } catch (cause) {
      fail("Could not save the cell", cause);
    }
  }

  async function bulkColumn(activity, mode: "attended" | "complete") {
    const eligible = (matrix.data?.members ?? []).filter((member) => !activity.exempted.includes(member.aptem_id));
    const confirmation = await Swal.fire({
      icon: "question",
      title: mode === "attended" ? "Mark everyone attended?" : "Complete for everyone?",
      text: `${eligible.length} members · "${activity.title}" · actual = ${activity.planned_hours} h each`,
      showCancelButton: true, confirmButtonText: "Apply",
    });
    if (!confirmation.isConfirmed) return;
    try {
      const result = await savePlanProgressBulk({
        activity_key: activity.activity_key,
        aptem_ids: eligible.map((member) => member.aptem_id),
        patch: mode === "attended"
          ? { status: "completed", attendance_status: "attended", actual_hours: activity.planned_hours, completion_date: activity.planned_date }
          : { status: "completed", actual_hours: activity.planned_hours, completion_date: activity.planned_date },
      });
      warnSigned(result.signed_warnings);
      toast(`${result.updated} learners updated`);
      await refresh();
    } catch (cause) {
      fail("Bulk update failed", cause);
    }
  }

  const activities = matrix.data?.activities ?? [];
  const members = matrix.data?.members ?? [];

  return (
    <div className="space-y-4 px-7 py-6">
      <div className="flex flex-wrap items-center gap-2">
        {data.months.map((item) => (
          <button key={item.month_index} type="button" onClick={() => onMonth(item.month_index)}
            className={`rounded-full px-3 py-1.5 text-xs font-semibold transition-colors ${item.month_index === activeMonth ? "bg-[#182d48] text-white" : "bg-secondary text-muted-foreground hover:text-foreground"}`}>
            M{item.month_index} · {item.label}
          </button>
        ))}
      </div>
      {matrix.isLoading && <p className="py-10 text-center text-sm text-muted-foreground">Building the matrix…</p>}
      {!matrix.isLoading && activities.length === 0 && <p className="py-10 text-center text-sm text-muted-foreground">No activities in this month yet — build the plan first.</p>}
      {activities.length > 0 && (
        <div className="overflow-x-auto rounded-lg border border-border">
          <table className="w-full min-w-[900px] border-collapse text-xs">
            <thead>
              <tr className="bg-[#182d48] text-white">
                <th className="sticky left-0 bg-[#182d48] px-3 py-2 text-left font-semibold">Learner</th>
                {activities.map((activity) => (
                  <th key={activity.activity_key} className="max-w-36 px-2 py-2 text-left align-bottom font-medium">
                    <span className="block truncate" title={activity.title}>W{activity.week_slot} · {activity.title}</span>
                    <span className="mt-1 flex gap-1">
                      <button type="button" onClick={() => void bulkColumn(activity, activity.category === "attendance" ? "attended" : "complete")}
                        className="rounded bg-white/10 px-1.5 py-0.5 text-[10px] font-semibold hover:bg-white/20">
                        {activity.category === "attendance" ? "all attended" : "all complete"}
                      </button>
                      {(activity.material_ref ?? "").startsWith("asg:") && (
                        <button type="button" onClick={() => setEvidenceFor(activity)}
                          className="rounded bg-white/10 px-1.5 py-0.5 text-[10px] font-semibold hover:bg-white/20">
                          docs
                        </button>
                      )}
                    </span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {members.map((member) => (
                <tr key={member.aptem_id} className="odd:bg-[#f7f9fc]">
                  <td className="sticky left-0 bg-inherit px-3 py-2 font-medium text-foreground">
                    {member.name ?? member.aptem_id}
                    {!member.lms_linked && <span className="ml-1 rounded bg-warning/20 px-1 py-0.5 text-[9px] font-semibold">no LMS link</span>}
                  </td>
                  {activities.map((activity) => {
                    if (activity.exempted.includes(member.aptem_id)) {
                      return <td key={activity.activity_key} className="px-2 py-2 text-center text-muted-foreground">—</td>;
                    }
                    const cell = matrix.data?.cells?.[`${member.aptem_id}:${activity.activity_key}`];
                    const progress = cell?.progress;
                    const suggestion = cell?.suggestion;
                    let glyph = "·";
                    let cls = "text-muted-foreground";
                    if (progress && !progress.rejected) {
                      if (progress.status === "completed") { glyph = "✓"; cls = "font-bold text-success"; }
                      else if (progress.status === "not_accepted") { glyph = "✕"; cls = "font-bold text-destructive"; }
                      else if (activity.category === "attendance" && progress.attendance_status === "absent") { glyph = "✗"; cls = "text-destructive"; }
                      else { glyph = "…"; cls = "text-foreground"; }
                    } else if (suggestion) {
                      // Ghost glyph: data says something happened, auditor has not confirmed.
                      if (suggestion.kind === "attendance") { glyph = suggestion.attended ? "✓?" : "✗?"; }
                      else { glyph = suggestion.completed ? "✓?" : "○?"; }
                      cls = "text-amber-600";
                    }
                    return (
                      <td key={activity.activity_key} className="px-2 py-1 text-center">
                        <button type="button" onClick={() => void editCell(member, activity, cell)}
                          title={progress ? `Confirmed: ${progress.status}` : suggestion ? "Suggested from data — click to confirm" : "Not recorded"}
                          className={`h-7 w-10 rounded transition-colors hover:bg-secondary ${cls}`}>
                          {glyph}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      <p className="text-xs text-muted-foreground">
        ✓ confirmed · ✓? / ✗? suggested from LMS/attendance data (click to confirm) · — exempted. Bulk buttons live in each column header.
      </p>
      {evidenceFor && <AssignmentEvidenceModal data={data} activity={evidenceFor} onClose={() => setEvidenceFor(null)} />}
    </div>
  );
}

// --- Members tab ---------------------------------------------------------------

function MembersTab({ data, refresh }: { data: PlanGroupDetail; refresh: () => Promise<unknown> | unknown }) {
  const queryClient = useQueryClient();
  const [selected, setSelected] = useState<Record<number, boolean>>({});
  const [seedGroup, setSeedGroup] = useState("");
  const [saving, setSaving] = useState(false);
  const suggestions = useQuery({ queryKey: ["plan-suggest", data.id], queryFn: () => suggestPlanMembers(data.id) });
  const lmsGroups = useQuery({ queryKey: ["plan-lms-groups"], queryFn: pickLmsGroups });
  // Membership changes affect the suggestions list plus every member-scoped
  // picker and the matrix — refresh them all.
  const invalidateMembershipDependents = () => Promise.all([
    queryClient.invalidateQueries({ queryKey: ["plan-suggest", data.id] }),
    queryClient.invalidateQueries({ queryKey: ["plan-att-sessions", data.id] }),
    queryClient.invalidateQueries({ queryKey: ["plan-assignments", data.id] }),
    queryClient.invalidateQueries({ queryKey: ["plan-materials", data.id] }),
    queryClient.invalidateQueries({ queryKey: ["plan-matrix", data.id] }),
  ]);

  const items = (suggestions.data?.items ?? []).filter((item) => !item.in_this_group);
  const sameProgramme = data.programme_name
    ? items.filter((item) => (item.programme ?? "").toLowerCase() === data.programme_name!.toLowerCase())
    : [];
  const chosen = Object.entries(selected).filter(([, v]) => v).map(([k]) => Number(k));

  async function seedFromLmsGroup(lmsGroupId: string) {
    setSeedGroup(lmsGroupId);
    if (!lmsGroupId) return;
    try {
      const seed = await pickLmsGroupMembers(Number(lmsGroupId));
      setSelected((current) => {
        const next = { ...current };
        for (const learner of seed.items) next[learner.aptem_id] = true;
        return next;
      });
      toast(`${seed.items.length} learners pre-selected from the LMS group`);
    } catch (cause) {
      fail("Could not load the LMS group", cause);
    }
  }

  async function add() {
    setSaving(true);
    try {
      const result = await updatePlanMembers(data.id, { add: chosen });
      setSelected({});
      toast(`${result.added.length} members added — their journals now carry the plan`);
      await Promise.all([refresh(), invalidateMembershipDependents()]);
    } catch (cause) {
      fail("Could not add the members", cause);
    } finally {
      setSaving(false);
    }
  }

  async function remove(aptemId: number) {
    const confirmation = await Swal.fire({
      icon: "warning", title: "Remove this member?",
      text: "The plan disappears from their journal; their recorded progress is kept.",
      showCancelButton: true, confirmButtonText: "Remove", confirmButtonColor: "#dc2626",
    });
    if (!confirmation.isConfirmed) return;
    try {
      await updatePlanMembers(data.id, { remove: [aptemId] });
      toast("Member removed");
      await Promise.all([refresh(), invalidateMembershipDependents()]);
    } catch (cause) {
      fail("Could not remove the member", cause);
    }
  }

  return (
    <div className="grid gap-6 px-7 py-6 lg:grid-cols-2">
      <div>
        <h3 className="mb-1 text-sm font-semibold text-foreground">Current members ({data.members.length})</h3>
        <p className="mb-3 text-xs text-muted-foreground">Everyone here shares the plan; only their progress differs.</p>
        <ul className="divide-y divide-border rounded-lg border border-border">
          {data.members.length === 0 && <li className="px-4 py-6 text-center text-xs text-muted-foreground">No members yet — pick them on the right.</li>}
          {data.members.map((member) => (
            <li key={member.aptem_id} className="flex items-center gap-3 px-4 py-2.5">
              <UsersRound className="h-4 w-4 text-muted-foreground" />
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-foreground">{member.name ?? member.aptem_id}</p>
                <p className="font-mono text-xs text-muted-foreground">Aptem ID: {member.aptem_id}</p>
              </div>
              <button type="button" onClick={() => void remove(member.aptem_id)} className="rounded p-1.5 text-destructive hover:bg-destructive/10"><Trash2 className="h-4 w-4" /></button>
            </li>
          ))}
        </ul>
      </div>
      <div>
        <div className="mb-3 flex flex-wrap items-center gap-2">
          <h3 className="text-sm font-semibold text-foreground">Add members</h3>
          <span className="flex-1" />
          <select className={`${field} max-w-56`} value={seedGroup} onChange={(e) => void seedFromLmsGroup(e.target.value)}>
            <option value="">Seed from LMS group…</option>
            {(lmsGroups.data?.items ?? []).map((option) => (
              <option key={option.group_id} value={option.group_id}>{option.name} ({option.learner_count})</option>
            ))}
          </select>
          {data.programme_name && sameProgramme.length > 0 && (
            <Button size="sm" variant="outline" onClick={() => setSelected((current) => {
              const next = { ...current };
              for (const item of sameProgramme) next[item.aptem_id] = true;
              return next;
            })}>Select programme matches ({sameProgramme.length})</Button>
          )}
          <Button size="sm" disabled={saving || chosen.length === 0} onClick={() => void add()}>Add {chosen.length || ""}</Button>
        </div>
        <div className="max-h-[32rem] overflow-auto rounded-lg border border-border">
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent">
                <TableHead className="w-10" />
                <TableHead className="label-caps">Learner</TableHead>
                <TableHead className="label-caps">Programme</TableHead>
                <TableHead className="label-caps">Status</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {items.map((item) => (
                <TableRow key={item.aptem_id}>
                  <TableCell>
                    <input type="checkbox" checked={!!selected[item.aptem_id]} onChange={(e) => setSelected((s) => ({ ...s, [item.aptem_id]: e.target.checked }))} />
                  </TableCell>
                  <TableCell>
                    <p className="text-sm font-medium text-foreground">{item.name ?? item.aptem_id}</p>
                    <p className="font-mono text-xs text-muted-foreground">
                      {item.aptem_id}{!item.lms_linked ? " · no LMS link" : ""}{item.in_other_group ? " · in another group" : ""}
                    </p>
                  </TableCell>
                  <TableCell className="max-w-52 truncate text-xs text-muted-foreground" title={item.programme ?? ""}>{item.programme ?? "—"}</TableCell>
                  <TableCell>
                    <span className={`rounded-full px-2 py-0.5 text-[11px] font-semibold ${item.status.toLowerCase() === "active" ? "bg-success/10 text-success" : item.status.toLowerCase() === "withdrawn" ? "bg-destructive/10 text-destructive" : "bg-muted text-muted-foreground"}`}>{item.status}</span>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </div>
    </div>
  );
}
